    word = "".join(c.lower() for c in word if 'a' <= c.lower() <= 'z')
    if not word:
        return 0

    vowels = "aeiouy"
    # Count groups of consecutive vowels
    count = len(re.findall(r'[aeiouy]+', word))

    # Silent e: ends in 'e' and more than one vowel group
